``` {.python .cell-code}
def valid_path(n, edges, source, destination):
    if source == destination:
        return True
    adj = undirected(n, edges, one=False)
    seen = [False] * n
    seen[source] = True
    q = deque([source])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if seen[v]:
                continue
            if v == destination:
                return True
            seen[v] = True
            q.append(v)
    return False


