bool canVisitAllRooms(vector<vector<int>>& rooms) {
    int n = rooms.size(), opened = 1;
    vector<char> seen(n);
    seen[0] = 1;
    vector<int> st = {0};
    while (!st.empty()) {
        int u = st.back();
        st.pop_back();
        for (int v : rooms[u]) if (!seen[v]) {
            seen[v] = 1;
            opened++;
            st.push_back(v);
        }
    }
    return opened == n;
