``` {.python .cell-code}
def counting_rooms(grid):
    g = [list(row) for row in grid]
    n, m = len(g), len(g[0])

    def flood(sr, sc):
        q = deque([(sr, sc)])
        g[sr][sc] = "#"
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and g[nr][nc] == ".":
                    g[nr][nc] = "#"
                    q.append((nr, nc))

    rooms = 0
    for r in range(n):
        for c in range(m):
            if g[r][c] == ".":
                rooms += 1
                flood(r, c)
    return rooms


