``` {.python .cell-code}
def counting_rooms_dsu(grid):
    n, m = len(grid), len(grid[0])
    parent = list(range(n * m))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a, b):
        a, b = find(a), find(b)
        if a != b:
            parent[a] = b

    for r in range(n):
        for c in range(m):
            if grid[r][c] != ".":
                continue
            i = r * m + c
            if r and grid[r - 1][c] == ".":
                unite(i, (r - 1) * m + c)
            if c and grid[r][c - 1] == ".":
                unite(i, r * m + (c - 1))
    return len({find(r * m + c) for r in range(n) for c in range(m) if grid[r][c] == "."})


def counting_rooms_bad_id(grid):
    """Same unions, with the row count in place of the column count."""
    n, m = len(grid), len(grid[0])
    parent = list(range(n * m + m))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def unite(a, b):
        a, b = find(a), find(b)
        if a != b:
            parent[a] = b

    for r in range(n):
        for c in range(m):
            if grid[r][c] != ".":
                continue
            i = r * n + c
            if r and grid[r - 1][c] == ".":
                unite(i, (r - 1) * n + c)
            if c and grid[r][c - 1] == ".":
                unite(i, r * n + (c - 1))
    return len({find(r * n + c) for r in range(n) for c in range(m) if grid[r][c] == "."})


