def max_area(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])

    def sink(r, c):
        if r < 0 or c < 0 or r >= R or c >= C or g[r][c] == 0:
            return 0
        g[r][c] = 0
        return 1 + sink(r + 1, c) + sink(r - 1, c) + sink(r, c + 1) + sink(r, c - 1)

    best = 0
    for r in range(R):
        for c in range(C):
            if g[r][c] == 1:
                best = max(best, sink(r, c))
    return best


