``` {.python .cell-code}
def two_buttons(n, m):
    if n == m:
        return 0
    HI = 2 * max(n, m)
    dist = [-1] * (HI + 1)
    dist[n] = 0
    q = deque([n])
    while q:
        x = q.popleft()
        for y in (2 * x, x - 1):
            if y < 1 or y > HI or dist[y] != -1:
                continue
            dist[y] = dist[x] + 1
            if y == m:
                return dist[y]
            q.append(y)
    return dist[m]


def two_buttons_narrow(n, m):
    HI = max(n, m)
    dist = [-1] * (HI + 1)
    dist[n] = 0
    q = deque([n])
    while q:
        x = q.popleft()
        for y in (2 * x, x - 1):
            if y < 1 or y > HI or dist[y] != -1:
                continue
            dist[y] = dist[x] + 1
            q.append(y)
    return dist[m]


