##### C++

```cpp
int twoButtons(int n, int m) {
    if (n == m) return 0;
    int HI = 2 * max(n, m);
    vector<int> dist(HI + 1, -1);
    queue<int> q;
    dist[n] = 0;
    q.push(n);
    while (!q.empty()) {
        int x = q.front();
        q.pop();
        int nxt[2] = {2 * x, x - 1};
        for (int y : nxt) {
            if (y < 1 || y > HI || dist[y] != -1) continue;
            dist[y] = dist[x] + 1;
            if (y == m) return dist[y];
            q.push(y);
        }
    }
    return dist[m];
}
```

