int openLock(vector<string>& deadends, string target) {
    vector<char> dead(10000);
    for (auto& s : deadends) dead[stoi(s)] = 1;
    if (dead[0]) return -1;
    int tgt = stoi(target);
    if (tgt == 0) return 0;
    vector<int> dist(10000, -1);
    queue<int> q;
    dist[0] = 0;
    q.push(0);
    int P[4] = {1000, 100, 10, 1};
    while (!q.empty()) {
        int x = q.front();
        q.pop();
        for (int w = 0; w < 4; w++) {
            int g = x / P[w] % 10;
            for (int step : {1, 9}) {
                int ng = (g + step) % 10;
                int y = x + (ng - g) * P[w];
                if (dead[y] || dist[y] != -1) continue;
                dist[y] = dist[x] + 1;
                if (y == tgt) return dist[y];
                q.push(y);
            }
