def open_lock_bi(deadends, target):
    dead = {int(s) for s in deadends}
    if 0 in dead:
        return -1
    tgt = int(target)
    if tgt == 0:
        return 0
    if tgt in dead:
        return -1
    P = (1000, 100, 10, 1)

    def neigh(x):
        out = []
        for w in range(4):
            g = x // P[w] % 10
            for step in (1, 9):
                ng = (g + step) % 10
                out.append(x + (ng - g) * P[w])
        return out

    fa = {0: 0}
    fb = {tgt: 0}
    qa, qb = deque([0]), deque([tgt])
    while qa and qb:
        if len(qa) > len(qb):
            qa, qb = qb, qa
            fa, fb = fb, fa
        for _ in range(len(qa)):
            x = qa.popleft()
            for y in neigh(x):
                if y in dead or y in fa:
                    continue
                if y in fb:
                    return fa[x] + 1 + fb[y]
                fa[y] = fa[x] + 1
                qa.append(y)
    return -1


