``` {.python .cell-code}
def longest_cycle(edges):
    n = len(edges)
    when = [-1] * n
    time = 0
    best = -1
    for s in range(n):
        if when[s] != -1:
            continue
        start = time
        v = s
        while v != -1 and when[v] == -1:
            when[v] = time
            time += 1
            v = edges[v]
        if v != -1 and when[v] >= start:
            best = max(best, time - when[v])
    return best


def longest_cycle_forget(edges):
    """Counts a hit on any earlier stamp, including a previous component."""
    n = len(edges)
    when = [-1] * n
    time = 0
    best = -1
    for s in range(n):
        if when[s] != -1:
            continue
        v = s
        while v != -1 and when[v] == -1:
            when[v] = time
            time += 1
            v = edges[v]
        if v != -1 and when[v] != -1:
            best = max(best, time - when[v])
    return best


