def longest_cycle_peel(edges):
    n = len(edges)
    indeg = [0] * n
    for v in edges:
        if v != -1:
            indeg[v] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    alive = [True] * n
    while q:
        u = q.popleft()
        alive[u] = False
        v = edges[u]
        if v != -1:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    best = -1
    seen = [False] * n
    for s in range(n):
        if not alive[s] or seen[s]:
            continue
        length = 0
        v = s
        while not seen[v]:
            seen[v] = True
            length += 1
            v = edges[v]
        best = max(best, length)
    return best


