```cpp
int longestCyclePeel(vector<int>& edges) {
    int n = edges.size();
    vector<int> indeg(n);
    for (int v : edges)
        if (v != -1) indeg[v]++;
    queue<int> q;
    vector<char> alive(n, 1);
    for (int i = 0; i < n; i++)
        if (indeg[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        alive[u] = 0;
        int v = edges[u];
        if (v != -1 && --indeg[v] == 0) q.push(v);
    }
    int best = -1;
    vector<char> seen(n);
    for (int s = 0; s < n; s++) {
        if (!alive[s] || seen[s]) continue;
        int length = 0, v = s;
        while (!seen[v]) {
            seen[v] = 1;
            length++;
            v = edges[v];
        }
        best = max(best, length);
    }
    return best;
}
```

