def find_duplicate(nums):
    tortoise = nums[0]
    hare = nums[nums[0]]
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[nums[hare]]
    tortoise = 0
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[hare]
    return tortoise


def find_duplicate_pairs(nums):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] == nums[j]:
                return nums[i]


def find_duplicate_from(nums, start):
    tortoise = nums[start]
    hare = nums[nums[start]]
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[nums[hare]]
    tortoise = start
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[hare]
    return tortoise


def find_duplicate_wrong_restart(nums):
    tortoise = nums[0]
    hare = nums[nums[0]]
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[nums[hare]]
    tortoise = nums[0]
    for _ in range(len(nums) + 2):
        if tortoise == hare:
            return tortoise
        tortoise = nums[tortoise]
        hare = nums[hare]
    return None


