``` {.python .cell-code}
def find_duplicate_brent(nums):
    tortoise = 0
    hare = nums[0]
    power = lam = 1
    while tortoise != hare:
        if power == lam:
            tortoise = hare
            power *= 2
            lam = 0
        hare = nums[hare]
        lam += 1
    tortoise = hare = 0
    for _ in range(lam):
        hare = nums[hare]
    while tortoise != hare:
        tortoise = nums[tortoise]
        hare = nums[hare]
    return tortoise


