int findDuplicateBrent(vector<int>& nums) {
    int tortoise = 0, hare = nums[0], power = 1, lam = 1;
    while (tortoise != hare) {
        if (power == lam) {
            tortoise = hare;
            power *= 2;
            lam = 0;
        }
        hare = nums[hare];
        lam++;
    }
    tortoise = hare = 0;
    for (int i = 0; i < lam; i++) hare = nums[hare];
    while (tortoise != hare) {
        tortoise = nums[tortoise];
        hare = nums[hare];
    }
    return tortoise;
}
```

