def lake_volume(grid):
    g = [row[:] for row in grid]
    R, C = len(g), len(g[0])
    best = 0
    for sr in range(R):
        for sc in range(C):
            if g[sr][sc] == 0:
                continue
            q = deque([(sr, sc)])
            volume = g[sr][sc]
            g[sr][sc] = 0
            while q:
                r, c = q.popleft()
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < R and 0 <= nc < C and g[nr][nc]:
                        volume += g[nr][nc]
                        g[nr][nc] = 0
                        q.append((nr, nc))
            best = max(best, volume)
    return best

