def count_sub(grid1, grid2):
    g2 = [row[:] for row in grid2]
    R, C = len(g2), len(g2[0])
    cnt = 0
    for sr in range(R):
        for sc in range(C):
            if g2[sr][sc] != 1:
                continue
            inside = True
            q = deque([(sr, sc)])
            g2[sr][sc] = 0
            while q:
