::: {#43a0de1f .cell execution_count=85}
``` {.python .cell-code}
def tour(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u - 1].append(v - 1)
    total = 0
    for s in range(n):
        seen = [False] * n
        seen[s] = True
        st = [s]
        cnt = 1
        while st:
            u = st.pop()
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    cnt += 1
                    st.append(v)
        total += cnt
    return total

assert tour(3, [(1, 2), (2, 3), (3, 2)]) == 7
