def min_reorder(n, connections):
    adj = [[] for _ in range(n)]
    for u, v in connections:
        adj[u].append((v, 1))
        adj[v].append((u, 0))
    seen = [False] * n
    seen[0] = True
    st = [0]
    flips = 0
    while st:
        u = st.pop()
        for v, cost in adj[u]:
            if not seen[v]:
                seen[v] = True
                flips += cost
                st.append(v)
    return flips

