::: {#878b8f9a .cell execution_count=87}
``` {.python .cell-code}
def path_ab(a, b):
    path = []
    x = b
    while x > a:
        path.append(x)
        if x % 2 == 0:
            x //= 2
        elif x % 10 == 1 and x // 10 >= a:
            x //= 10
        else:
            return None
    if x != a:
        return None
    path.append(a)
    path.reverse()
    return path

assert path_ab(2, 162) == [2, 4, 8, 81, 162]
assert path_ab(4, 42) is None
assert path_ab(100, 40021) == [100, 200, 2001, 4002, 40021]
